2	#include "memmap.hpp"
3	
4	#include <cstdio>
5	#include <cstdlib>
6	
7	#include "hybrid/state_abi.h"  // HYBRID_V_SCRATCH_BYTES
8	
9	namespace andes_sim {
10	namespace {
11	
12	// AE350 platform constants shared by BOTH engines (QEMU andes_ae350.c memmap
13	// table; vsim src/platform/memory_map.h). The print-memmap contract test
14	// cross-checks these against the engine's own dump.
15	constexpr uint64_t kSimControlBase = 0xe0080000;
16	constexpr uint64_t kSimControlSize = 0x1000;
17	constexpr uint64_t kUart2Base = 0xf0300000;
18	constexpr uint64_t kUart2Size = 0x100000;
19	
20	// Strip one trailing '\r' (the cfg may come from a CRLF-writing engine) and
21	// surrounding spaces/tabs.
22	std::string trim(const std::string& s) {
23	  size_t b = s.find_first_not_of(" \t\r");
24	  if (b == std::string::npos) return "";
25	  size_t e = s.find_last_not_of(" \t\r");
26	  return s.substr(b, e - b + 1);
27	}
28	
29	// `key = "value"` -> value (quotes optional); "" when the line is not `key = ...`.
30	std::string ini_value(const std::string& line, const char* key) {
31	  const std::string t = trim(line);
32	  const std::string pfx = std::string(key);
33	  if (t.compare(0, pfx.size(), pfx) != 0) return "";
34	  size_t i = pfx.size();
35	  while (i < t.size() && (t[i] == ' ' || t[i] == '\t')) ++i;
36	  if (i >= t.size() || t[i] != '=') return "";
37	  ++i;
38	  while (i < t.size() && (t[i] == ' ' || t[i] == '\t')) ++i;
39	  std::string v = t.substr(i);
40	  if (v.size() >= 2 && v.front() == '"' && v.back() == '"')
41	    v = v.substr(1, v.size() - 2);
42	  return v;
43	}
44	
45	}  // namespace
46	
47	std::map<std::string, std::string> qemu_cfg_soc_props(
48	    const std::string& cfg_text) {
49	  std::map<std::string, std::string> out;
50	  // Each [global] block carries driver/property/value lines (any order per
51	  // QEMU's -readconfig grammar; the engine emits driver first). Collect the
52	  // triple per block; commit it when the block ends or the text does.
53	  std::string drv, prop, val;
54	  bool have_val = false;
55	  auto commit = [&] {
56	    if (drv == "riscv.andes.ae350.soc" && !prop.empty() && have_val)
57	      out[prop] = val;
58	    drv.clear();
59	    prop.clear();
60	    val.clear();
61	    have_val = false;
62	  };
63	  size_t pos = 0;
64	  while (pos <= cfg_text.size()) {
65	    const size_t nl = cfg_text.find('\n', pos);
66	    const std::string line =
67	        cfg_text.substr(pos, nl == std::string::npos ? nl : nl - pos);
68	    const std::string t = trim(line);
69	    if (t == "[global]") {
70	      commit();
71	    } else if (std::string v = ini_value(line, "driver"); !v.empty()) {
72	      drv = v;
73	    } else if (std::string v = ini_value(line, "property"); !v.empty()) {
74	      prop = v;
75	    } else if (std::string v = ini_value(line, "value"); !v.empty()) {
76	      val = v;
77	      have_val = true;
78	    }
79	    if (nl == std::string::npos) break;
80	    pos = nl + 1;
81	  }
82	  commit();
83	  return out;
84	}
85	
86	MemmapResult hybrid_memmap(const EngineDescriptor& eng, long long mem_size,
87	                           const std::string& qemu_cfg_text) {
88	  MemmapResult r;
89	  const uint64_t mem = static_cast<uint64_t>(mem_size);
90	
91	  r.rows.push_back({"DRAM", 0, mem - 1,
92	                    "shared mmap; content survives the handoff"});
93	  r.rows.push_back({"V-scratch", mem, mem + HYBRID_V_SCRATCH_BYTES - 1,
94	                    "reserved by the hybrid V transport; not program-usable"});
95	
96	  const auto props = qemu_cfg_soc_props(qemu_cfg_text);
97	  // ilm/dlm/hvm rows need BOTH a transportable size (descriptor, backdoor-
98	  // gated) AND the base from the engine's cfg. Sizes come from the descriptor:
99	  // they are the bytes the sidecar actually carries.
100	  auto base_of = [&](const char* key) -> const std::string* {
101	    auto it = props.find(key);
102	    return it == props.end() ? nullptr : &it->second;
103	  };
104	  bool geometry_missing = false;
105	  auto lm_row = [&](const char* region, const char* base_key, long size,
106	                    const std::string& transport) {
107	    if (size <= 0) return;  // engine cannot transport it -> unsupported -> omit
108	    const std::string* b = base_of(base_key);
109	    if (!b) {
110	      geometry_missing = true;
111	      return;
112	    }
113	    const uint64_t base = std::strtoull(b->c_str(), nullptr, 0);
114	    r.rows.push_back(
115	        {region, base, base + static_cast<uint64_t>(size) - 1, transport});
116	  };
117	  lm_row("ILM", "ilm_base", eng.ilm_size,
118	         "sidecar .ilm; DRAM overlay while milmb.IEN=1");
119	  lm_row("DLM", "dlm_base", eng.dlm_size,
120	         "sidecar .dlm; DRAM overlay while mdlmb.IEN=1");
121	  lm_row("HVM", "hvm_base", eng.hvm_size, "sidecar .hvm");
122	  if (geometry_missing)
123	    r.warnings.push_back(
124	        "engine '" + eng.id +
125	        "' reports transportable local memories but its --print-qemu-config "
126	        "gave no geometry; ILM/DLM/HVM rows omitted");
127	
128	  r.rows.push_back({"SimControl/HTIF", kSimControlBase,
129	                    kSimControlBase + kSimControlSize - 1,
130	                    "device; state does not cross the handoff"});
131	  r.rows.push_back({"UART2", kUart2Base, kUart2Base + kUart2Size - 1,
132	                    "device (console); state does not cross the handoff"});
133	  return r;
134	}
135	
136	std::string fmt_size(uint64_t bytes) {
137	  constexpr uint64_t kK = 1024, kM = kK * 1024, kG = kM * 1024;
138	  char buf[32];
139	  if (bytes >= kG && bytes % kG == 0)
140	    std::snprintf(buf, sizeof buf, "%lluG",
141	                  static_cast<unsigned long long>(bytes / kG));
142	  else if (bytes >= kM && bytes % kM == 0)
