2	#include "shm.hpp"
3	
4	#include <cctype>
5	#include <cstdio>
6	#include <cstdlib>
7	#include <filesystem>
8	#include <regex>
9	#include <vector>
10	
11	#include <sys/stat.h>
12	#include <sys/statvfs.h>
13	#include <unistd.h>
14	
15	#include "hybrid/state_abi.h"  // HYBRID_V_SCRATCH_BYTES (L26/F2)
16	#include "log.hpp"
17	
18	namespace andes_sim {
19	namespace {
20	
21	// Free bytes on the filesystem holding `dir`, or -1 if it does not exist.
22	long long free_bytes(const std::string& dir) {
23	  struct statvfs vfs;
24	  if (statvfs(dir.c_str(), &vfs) != 0) return -1;
25	  return static_cast<long long>(vfs.f_bavail) *
26	         static_cast<long long>(vfs.f_frsize);
27	}
28	
29	// Human-readable byte count: "8.0 GiB", "512.0 MiB", "1024 B" (one decimal,
30	// TiB/GiB/MiB/KiB, else "N B").
31	std::string format_bytes(long long n) {
32	  struct Unit {
33	    const char* suffix;
34	    long long mul;
35	  };
36	  static const Unit units[] = {
37	      {"TiB", 1024LL * 1024 * 1024 * 1024},
38	      {"GiB", 1024LL * 1024 * 1024},
39	      {"MiB", 1024LL * 1024},
40	      {"KiB", 1024LL},
41	  };
42	  for (const Unit& u : units) {
43	    if (n >= u.mul) {
44	      char buf[64];
45	      std::snprintf(buf, sizeof(buf), "%.1f %s",
46	                    static_cast<double>(n) / static_cast<double>(u.mul),
47	                    u.suffix);
48	      return buf;
49	    }
50	  }
51	  return std::to_string(n) + " B";
52	}
53	
54	}  // namespace
55	
56	long long parse_size(const std::string& spec, std::string& err) {
57	  static const std::regex re(R"(\s*(\d+(?:\.\d+)?)\s*([KMGT]?)\s*)",
58	                             std::regex::icase);
59	  std::smatch m;
60	  if (!std::regex_match(spec, m, re)) {
61	    err = "invalid mmap size '" + spec +
62	          "': expected <number>[K|M|G|T] (e.g. '128M', '8G', '1024')";
63	    return 0;
64	  }
65	  const double num = std::stod(m[1].str());
66	  long long mult = 1;
67	  if (m[2].length()) {
68	    switch (std::toupper(static_cast<unsigned char>(m[2].str()[0]))) {
69	      case 'K': mult = 1024LL; break;
70	      case 'M': mult = 1024LL * 1024; break;
71	      case 'G': mult = 1024LL * 1024 * 1024; break;
72	      case 'T': mult = 1024LL * 1024 * 1024 * 1024; break;
73	    }
74	  }
75	  // Truncate toward zero like Python int(float(num) * multiplier).
76	  const long long size =
