169	// `run --mode fast`: QEMU alone, functional, transparent passthrough. Needs
170	// only the built-in qemu descriptor, so it resolves that directly rather than
171	// discover_engines(), which would spawn a --describe subprocess per Verilator
172	// build only to discard them all here.
173	int run_fast(const Cli& cli) {
174	  // fast is QEMU-only; an explicit engine must name 'qemu64' (rv64) or 'qemu32'.
175	  if (!cli.engine.empty() && cli.engine != kQemuId64 && cli.engine != kQemuId32) {
176	    std::fprintf(stderr,
177	                 "andesim run --mode fast: engine must be 'qemu64' or 'qemu32', "
178	                 "got '%s'\n",
179	                 cli.engine.c_str());
180	    return 2;
181	  }
182	  // --runtime linux (U2, ROADMAP_LINUX_RUNTIME.md) defaults --mem-size to 1G
183	  // (the app + vlinux's own arenas) when the user did not pick one.
184	  std::string mem_size_spec = cli.mem_size;
185	  if (cli.runtime == "linux" && mem_size_spec.empty()) mem_size_spec = "1G";
186	
187	  // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
188	  // default injected). It precedes the post-`--` args, so a user's own -m wins.
189	  std::string err;
190	  std::vector<std::string> extra = qemu_m_args(mem_size_spec, err);
191	  if (!err.empty()) {
192	    std::fprintf(stderr, "andesim run --mode fast: %s\n", err.c_str());
193	    return 2;
194	  }
195	  // --gdb: inject QEMU's built-in GDB stub and pause at startup.
196	  if (cli.gdb) {
197	    const std::string port = cli.gdb_port.empty() ? "1234" : cli.gdb_port;
198	    extra.push_back("-gdb");
199	    extra.push_back("tcp::" + port);
200	    extra.push_back("-S");
201	  }
202	
203	  // --runtime linux: stage a manifested vlinux.elf that boots the app under
204	  // the proxy kernel. The ELF positional is the APP, not the boot image --
205	  // -bios loads the staged vlinux instead (run_standalone's boot_elf_override).
206	  Cli cli2 = cli;
207	  std::string boot_elf;
208	  if (cli.runtime == "linux") {
209	    if (int rc = check_one_elf(cli, "fast")) return rc;
210	    const std::string app_elf =
211	        abs_elf(cli.positional[0], "--mode fast --runtime linux");
212	    if (app_elf.empty()) return 2;
213	
214	    // mem_size_spec already passed qemu_m_args above (whole-MiB check, a
215	    // strictly tighter validation than parse_size alone), so this call
216	    // cannot fail: reused only to get the byte count for the manifest.
217	    const long long mem_bytes = parse_size(mem_size_spec, err);
218	
219	    std::string stage_err;
220	    boot_elf = stage_linux_runtime(app_elf, static_cast<uint64_t>(mem_bytes),
221	                                   cli.passthrough, stage_err);
222	    if (boot_elf.empty()) {
223	      std::fprintf(stderr, "andesim run --mode fast --runtime linux: %s\n",
224	                   stage_err.c_str());
225	      return 2;
226	    }
227	    log_line(kLogInfo, "[andesim] --runtime linux: staged %s (app=%s)",
228	             boot_elf.c_str(), app_elf.c_str());
229	
230	    // App argv (ROADMAP_LINUX_RUNTIME.md U8) travels through the manifest
231	    // above, not QEMU's own CLI -- clear it here so QEMU never sees it as
232	    // engine flags (e.g. "-m x.gguf" is not a memory size).
233	    cli2.passthrough.clear();
234	
235	    // Engine-synced CPU: the app + vlinux run on the hardware a hybrid
236	    // measurement targets, not the ax46 vplat default (last -cpu wins).
237	    extra.push_back("-cpu");
238	    extra.push_back("andes-ax45mpv,vlen=512");
239	  }
240	
241	  // Pick rv32 vs rv64. An explicit --engine (qemu32/qemu64) wins; otherwise read
242	  // the ELF's class so an rv32 program lands on qemu-system-riscv32 instead of
243	  // the rv64 default. Warn (do not fail) if an explicit choice contradicts the
244	  // ELF -- the override is the user's call.
245	  const int elf_w = cli.positional.empty() ? 0 : elf_xlen(cli.positional[0]);
246	  int xlen;
247	  if (cli.engine == kQemuId32) xlen = 32;
248	  else if (cli.engine == kQemuId64) xlen = 64;
249	  else xlen = elf_w ? elf_w : 64;  // no explicit engine: follow the ELF (else rv64)
250	  // Only an explicit engine can disagree with the ELF (when none is given, xlen
251	  // == elf_w), so this guard already implies an explicit --engine.
252	  if (elf_w && elf_w != xlen)
253	    std::fprintf(stderr,
254	                 "[andesim] --mode fast: --engine %s is rv%d but the ELF is rv%d "
255	                 "(running as rv%d)\n",
256	                 cli.engine.c_str(), xlen, elf_w, xlen);
257	  return run_standalone(cli2, builtin_qemu_arch(xlen), "fast", extra,
258	                        /*clean_output=*/false, boot_elf);
259	}
