261	// Block until 127.0.0.1:`port` is LISTENing (or `timeout_ms` elapses). vsim opens
262	// its --jtag-port only after it has reset and halted the hart, so the debugger we
263	// exec next must not race ahead of it -- OpenOCD/ICEman do not retry the bitbang
264	// connect, and a missed connect leaves the session dead. Non-intrusive: scans
265	// /proc/net/tcp rather than connecting (a probe connection would land in vsim's
266	// single debugger slot). Returns false on timeout.
267	static bool wait_for_jtag_port(uint16_t port, int timeout_ms = 20000) {
268	  constexpr int kPollMs = 50;
269	  for (int waited = 0; waited <= timeout_ms; waited += kPollMs) {
270	    if (std::FILE* f = std::fopen("/proc/net/tcp", "re")) {
271	      char line[512];
272	      while (std::fgets(line, sizeof line, f)) {
273	        // cols: sl  local_address(IP:port hex)  rem_address  st  ...
274	        // "%*8x:%x" skips the 8-hex-digit IPv4 and reads the local port; the
275	        // 0A (TCP_LISTEN) filter also drops the non-hex header row.
276	        unsigned lport = 0, st = 0;
277	        if (std::sscanf(line, "%*s %*8x:%x %*s %x", &lport, &st) == 2
278	            && st == 0x0A && lport == port) {
279	          std::fclose(f);
280	          return true;
281	        }
282	      }
283	      std::fclose(f);
284	    }
285	    std::this_thread::sleep_for(std::chrono::milliseconds(kPollMs));
286	  }
287	  return false;
288	}
