290	// `run --mode cycle --gdb`: start vsim with --jtag-port 9104 in the background
291	// (the hart free-runs; ICEman halts it over the JTAG DTM on connect), then exec
292	// ICEman ($ICEMAN env var) with `-Z v5 -I virtual_dmi.cfg` in the foreground.
293	int run_cycle_gdb(const Cli& cli, const EngineDescriptor& eng) {
294	  const char* iceman = std::getenv("ICEMAN");
295	  if (!iceman || !*iceman) {
296	    std::fprintf(stderr,
297	                 "andesim run --mode cycle --gdb: $ICEMAN not set "
298	                 "(export ICEMAN=<path to ICEman binary>)\n");
299	    return 2;
300	  }
301	  // Build vsim argv from the standalone template, appending user passthrough
302	  // and the JTAG port flag.
303	  const std::string elf = abs_elf(cli.positional[0], "--mode cycle --gdb");
304	  if (elf.empty()) return 2;
305	  const std::string jtag_port = cli.gdb_port.empty() ? "9104" : cli.gdb_port;
306	  std::vector<std::string> vsim_pass = cli.passthrough;
307	  vsim_pass.push_back("--jtag-port");
308	  vsim_pass.push_back(jtag_port);
309	  std::string err;
310	  const std::vector<std::string> vsim_argv =
311	      passthrough_argv(eng, "standalone", elf, vsim_pass, err);
312	  if (!err.empty()) {
313	    std::fprintf(stderr, "andesim run --mode cycle --gdb: %s\n", err.c_str());
314	    return 2;
315	  }
316	  std::fprintf(stderr,
317	               "[andesim] --gdb: vsim JTAG on port %s, exec ICEman\n",
318	               jtag_port.c_str());
319	  if (fork_background(vsim_argv) < 0) {
320	    std::fprintf(stderr,
321	                 "andesim run --mode cycle --gdb: failed to fork vsim\n");
322	    return 1;
323	  }
324	  // vsim opens the JTAG port and the hart free-runs; ICEman halts it on connect.
325	  // Wait for the port to be LISTENing before launching the debugger (it does not
326	  // retry the bitbang connect). Numeric ports only; a non-numeric --gdb-port
327	  // (atoi -> 0) skips the wait and lets the engine reject it. Best-effort: warn
328	  // but launch anyway if it never appears.
329	  if (const int pnum = std::atoi(jtag_port.c_str());
330	      pnum > 0 && !wait_for_jtag_port(static_cast<uint16_t>(pnum)))
331	    std::fprintf(stderr,
332	                 "[andesim] --gdb: warning: vsim JTAG port %s not LISTENing "
333	                 "after 20s; launching the debugger anyway\n",
334	                 jtag_port.c_str());
335	  // -I virtual_dmi.cfg selects ICEman's remote_bitbang interface (host
